package Q5;
public class SeatBooking{private final boolean[]booked;private int bookingsMade=0;SeatBooking(int n){booked=new boolean[n];}public synchronized boolean book(int seat){if(seat<0||seat>=booked.length)throw new IllegalArgumentException();if(booked[seat])return false;booked[seat]=true;bookingsMade++;return true;}public static void main(String[]x)throws InterruptedException{SeatBooking s=new SeatBooking(10);Thread[]users=new Thread[100];for(int i=0;i<100;i++){final int seat=i%10;users[i]=new Thread(()->s.book(seat));users[i].start();}for(Thread t:users)t.join();System.out.println("Seats sold: "+s.bookingsMade);}}
